/*
 * TerraZ hero compatibility fixes.
 * The legacy mgGlitch plugin was no longer used; this loaded slot now keeps
 * the connection actions synchronized, promotes the information portal and
 * replaces opaque social PNGs with vector/font icons.
 */
(function (window, document) {
  "use strict";

  function addStyles() {
    if (document.getElementById("hero-compatibility-fixes")) {
      return;
    }

    var style = document.createElement("style");
    style.id = "hero-compatibility-fixes";
    style.textContent = [
      ".hero-1 .front-content.page-enter-animated .server-actions-block{transform:translateY(100%)!important;opacity:0!important}",
      ".hero-1 .front-content.page-enter-animated.show .server-actions-block{transition:1s 1s;transform:translateY(0)!important;opacity:1!important}",
      ".hero-1 .front-content.page-enter-animated .server-actions-block .server-address-row{transform:none!important;opacity:1!important;transition:none!important}",
      ".hero-1 .front-content .server-actions-block .hero-secondary-links{margin-bottom:24px}",
      ".hero-1 .front-content .social-links-row .social-link::before{content:none!important;display:none!important}",
      ".hero-1 .front-content .social-links-row .social-icon{display:block;font-size:19px;line-height:1;color:currentColor;opacity:.94;transform:scale(1);transition:opacity .22s ease,transform .22s ease}",
      ".hero-1 .front-content .social-links-row .social-icon-discord{width:34px;height:34px;fill:currentColor}",
      ".hero-1 .front-content .social-links-row .social-link:hover .social-icon,.hero-1 .front-content .social-links-row .social-link:focus-visible .social-icon{opacity:1;transform:scale(1.08)}",
      ".hero-portal-link{position:absolute;z-index:20;top:28px;right:30px;display:inline-flex;align-items:center;gap:12px;min-width:196px;padding:11px 14px 11px 16px;color:#efffff;border:1px solid rgba(190,255,251,.28);border-radius:8px;background:rgba(7,24,25,.68);box-shadow:0 8px 26px rgba(0,0,0,.22);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);text-align:left;transform:translateY(0);transition:transform .22s ease,border-color .22s ease,background-color .22s ease,box-shadow .22s ease}",
      ".hero-portal-link:hover,.hero-portal-link:focus-visible{color:#fff;border-color:rgba(113,231,223,.9);background:rgba(18,72,71,.78);box-shadow:0 12px 30px rgba(0,0,0,.3),0 0 22px rgba(31,184,178,.14);transform:translateY(-2px);outline:none}",
      ".hero-portal-copy{display:flex;flex-direction:column;flex:1;min-width:0}",
      ".hero-portal-domain{font-family:'Open Sans',sans-serif;font-size:9px;font-weight:600;line-height:1.2;letter-spacing:.13em;color:#71e7df}",
      ".hero-portal-title{margin-top:3px;font-family:Raleway,sans-serif;font-size:13px;font-weight:400;line-height:1.2;letter-spacing:.04em;white-space:nowrap;color:#fff}",
      ".hero-portal-link .fa{font-size:13px;color:#71e7df;transition:transform .22s ease}",
      ".hero-portal-link:hover .fa,.hero-portal-link:focus-visible .fa{transform:translateX(3px)}",
      ".hero-1 .front-content.page-enter-animated .hero-portal-link{opacity:0;transform:translateY(-14px)}",
      ".hero-1 .front-content.page-enter-animated.show .hero-portal-link{opacity:1;transform:translateY(0);transition:opacity .7s 1.1s ease,transform .7s 1.1s ease,border-color .22s ease,background-color .22s ease,box-shadow .22s ease}",
      "@media only screen and (max-width:600px),only screen and (max-height:560px){.hero-1 .front-content .container-mid.hero-composition{box-sizing:border-box!important;width:100%!important;max-height:calc(100vh - 12px)!important;max-height:calc(100svh - 12px)!important;padding:46px 12px 12px!important;overflow-y:auto!important;overscroll-behavior:contain;scrollbar-width:none;-ms-overflow-style:none}.hero-1 .front-content .container-mid.hero-composition::-webkit-scrollbar{display:none}.hero-1 .front-content .hero-composition>svg{width:min(144px,44vw)!important;max-width:44vw!important;margin-bottom:9px!important}.hero-1 .front-content .hero-message-block{margin-bottom:12px!important}.hero-1 .front-content .hero-message h1{font-size:clamp(32px,10.5vw,42px)!important;line-height:.93!important;margin-bottom:6px!important}.hero-1 .front-content .hero-subtitle{padding:0 10px;font-size:8px!important;line-height:1.35!important;letter-spacing:.09em!important}.hero-1 .front-content .server-actions-block{width:100%!important}.hero-1 .front-content .server-address-row{margin-bottom:8px!important}.hero-1 .front-content mark.server-copy{width:min(330px,calc(100vw - 24px))!important;min-height:48px!important}.hero-1 .front-content mark.server-copy url{padding:0 12px!important;font-size:14.5px!important;letter-spacing:.025em!important}.hero-1 .front-content .copy-action{min-width:48px!important;padding:0 12px!important}.hero-1 .front-content .server-actions-block .hero-secondary-links{margin:0 0 11px!important;font-size:10px!important;letter-spacing:.06em!important}.hero-1 .front-content .social-links-row{gap:8px!important}.hero-1 .front-content .social-links-row .social-link{width:36px!important;height:36px!important}.hero-1 .front-content .social-links-row .social-icon{font-size:16px}.hero-1 .front-content .social-links-row .social-icon-discord{width:31px;height:31px}.hero-portal-link{top:10px;right:10px;justify-content:center;width:38px;height:38px;min-width:38px;padding:0;gap:0;border-radius:50%}.hero-portal-copy{display:none}.hero-portal-link .fa{font-size:12px}}",
      "@media only screen and (max-width:340px){.hero-1 .front-content .hero-composition>svg{width:128px!important;max-width:42vw!important}.hero-1 .front-content .hero-message h1{font-size:31px!important}.hero-1 .front-content mark.server-copy url{font-size:13px!important}.hero-1 .front-content .social-links-row .social-link{width:34px!important;height:34px!important}.hero-1 .front-content .social-links-row .social-icon-discord{width:29px;height:29px}}",
      "@media only screen and (max-height:420px){.hero-1 .front-content .container-mid.hero-composition{max-height:calc(100vh - 4px)!important;max-height:calc(100svh - 4px)!important;padding:8px 10px 6px!important}.hero-1 .front-content .hero-composition>svg{width:108px!important;max-width:32vw!important;margin-bottom:4px!important}.hero-1 .front-content .hero-message-block{margin-bottom:6px!important}.hero-1 .front-content .hero-message h1{font-size:28px!important;margin-bottom:3px!important}.hero-1 .front-content .hero-subtitle{display:none}.hero-1 .front-content mark.server-copy{min-height:42px!important}.hero-1 .front-content .server-address-row{margin-bottom:5px!important}.hero-1 .front-content .server-actions-block .hero-secondary-links{margin-bottom:6px!important;font-size:9px!important}.hero-1 .front-content .social-links-row .social-link{width:30px!important;height:30px!important}.hero-1 .front-content .social-links-row .social-icon{font-size:14px}.hero-1 .front-content .social-links-row .social-icon-discord{width:26px;height:26px}.hero-portal-link{top:6px;right:6px;width:32px;height:32px;min-width:32px}.hero-portal-link .fa{font-size:10px}}",
      "@media (prefers-reduced-motion:reduce){.hero-1 .front-content.page-enter-animated .server-actions-block,.hero-1 .front-content.page-enter-animated.show .server-actions-block,.hero-1 .front-content.page-enter-animated .hero-portal-link,.hero-1 .front-content.page-enter-animated.show .hero-portal-link{transition:none!important;transform:none!important;opacity:1!important}}"
    ].join("");
    document.head.appendChild(style);
  }

  function groupServerActions() {
    var addressRow = document.querySelector(".server-address-row");
    var secondaryLinks = document.querySelector(".hero-secondary-links");

    if (!addressRow || !secondaryLinks || (addressRow.parentNode === secondaryLinks.parentNode && addressRow.parentNode.classList.contains("server-actions-block"))) {
      return;
    }

    var wrapper = document.createElement("div");
    wrapper.className = "server-actions-block";
    addressRow.parentNode.insertBefore(wrapper, addressRow);
    wrapper.appendChild(addressRow);
    wrapper.appendChild(secondaryLinks);
  }

  function updateConnectionLinks() {
    var secondaryLinks = document.querySelector(".hero-secondary-links");
    if (!secondaryLinks) {
      return;
    }

    var steamLink = secondaryLinks.querySelector('a[href^="steam://"]');
    if (steamLink) {
      steamLink.textContent = "Играть через Steam";
      steamLink.setAttribute("aria-label", "Играть на TerraZ через Steam");
    }

    var funLink = secondaryLinks.querySelector('a[href*="fun.terraz.ru"]');
    if (funLink) {
      var separator = funLink.previousElementSibling;
      if (separator && separator.tagName.toLowerCase() === "span") {
        separator.parentNode.removeChild(separator);
      }
      funLink.parentNode.removeChild(funLink);
    }

    secondaryLinks.setAttribute("aria-label", "Запуск Terraria");
  }

  function ensurePortalLink() {
    var frontContent = document.querySelector(".hero-1 .front-content");
    if (!frontContent || frontContent.querySelector(".hero-portal-link")) {
      return;
    }

    var portalLink = document.createElement("a");
    portalLink.className = "hero-portal-link";
    portalLink.href = "https://fun.terraz.ru/";
    portalLink.setAttribute("aria-label", "Открыть основной сайт TerraZ с информацией о сервере");
    portalLink.innerHTML =
      '<span class="hero-portal-copy">' +
        '<span class="hero-portal-domain">FUN.TERRAZ.RU</span>' +
        '<span class="hero-portal-title">Всё о сервере</span>' +
      "</span>" +
      '<i class="fa fa-arrow-right" aria-hidden="true"></i>';

    frontContent.insertBefore(portalLink, frontContent.firstChild);
  }

  function discordIcon() {
    return '<svg class="social-icon social-icon-discord" viewBox="0 0 24 24" aria-hidden="true" focusable="false">' +
      '<path d="M7 7.6c1.5-.7 3.2-1.1 5-1.1s3.5.4 5 1.1c1.1 1.7 1.8 3.7 2 5.8-.9 1.2-2 2.2-3.3 2.9l-.8-1.1c.8-.4 1.5-.8 2.1-1.3-1.6.8-3.3 1.2-5 1.2s-3.4-.4-5-1.2c.6.5 1.3.9 2.1 1.3l-.8 1.1C7 15.6 5.9 14.6 5 13.4c.2-2.1.9-4.1 2-5.8zm2.2 3.1c-.6 0-1.1.6-1.1 1.3s.5 1.3 1.1 1.3 1.1-.6 1.1-1.3-.5-1.3-1.1-1.3zm5.6 0c-.6 0-1.1.6-1.1 1.3s.5 1.3 1.1 1.3 1.1-.6 1.1-1.3-.5-1.3-1.1-1.3z"/>' +
      "</svg>";
  }

  function replaceSocialIcons() {
    var icons = [
      ['a.social-link[href*="vk.com"]', '<i class="fa fa-vk social-icon" aria-hidden="true"></i>'],
      ['a.social-link[href*="youtube.com"]', '<i class="fa fa-youtube-play social-icon" aria-hidden="true"></i>'],
      ['a.social-link[href="/conference"]', discordIcon()],
      ['a.social-link[href*="t.me"]', '<i class="fa fa-paper-plane social-icon" aria-hidden="true"></i>'],
      ['a.social-link[href*="twitch.tv"]', '<i class="fa fa-twitch social-icon" aria-hidden="true"></i>']
    ];

    icons.forEach(function (item) {
      var link = document.querySelector(item[0]);
      if (link) {
        link.innerHTML = item[1];
      }
    });
  }

  function applyFixes() {
    groupServerActions();
    updateConnectionLinks();
    ensurePortalLink();
    replaceSocialIcons();
  }

  addStyles();

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () {
      window.setTimeout(applyFixes, 0);
    });
  } else {
    window.setTimeout(applyFixes, 0);
  }
}(window, document));